"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[527],{1487:(e,a,o)=>{o.d(a,{s:()=>i});let i=[{slug:"mecanica-lab",index:"01",code:"IV-LAB // 01",maturity:"application",statusBadge:{pt:"Aplica\xe7\xe3o Educacional Interativa (Demo Publicada)",en:"Interactive Educational Application (Live Demo)"},title:{pt:"Mec\xe2nica Lab — Plataforma Interativa de Ensino T\xe9cnico",en:"Mec\xe2nica Lab — Interactive Technical Learning Platform"},subtitle:{pt:"Oficina 2D, laborat\xf3rio 3D de desmontagem de bomba centr\xedfuga e simuladores de metrologia no navegador.",en:"2D workshop, 3D centrifugal pump disassembly lab, and browser-based metrology simulators."},category:{pt:"Tecnologia Educacional \xb7 Web 3D \xb7 Simula\xe7\xe3o Mec\xe2nica",en:"Educational Technology \xb7 3D Web \xb7 Mechanical Simulation"},year:"2026",heroImage:"/projects/mecanica-lab/inicio.png",liveUrl:"https://mecanica-lab-3d.netlify.app",githubUrl:"https://github.com/italovienna-sketch/mecanica-lab",disclaimer:{pt:"Projeto pessoal e independente, sem v\xednculo oficial com nenhuma empresa ou institui\xe7\xe3o. Os dados s\xe3o fict\xedcios e os modelos s\xe3o educacionais e simplificados — concebidos para complementar, e nunca substituir, o professor, a oficina e a pr\xe1tica supervisionada.",en:"Personal, independent project with no official affiliation with any company or institution. Data is fictional and models are simplified for educational purposes — designed to complement, never replace, instructors, workshops, and supervised practice."},overview:{pt:"O Mec\xe2nica Lab nasceu de uma observa\xe7\xe3o direta durante os estudos de mec\xe2nica industrial: aprender elementos de m\xe1quinas, metrologia e manuten\xe7\xe3o apenas por apostilas est\xe1ticas dificulta a visualiza\xe7\xe3o espacial de como cada componente interage. A plataforma re\xfane uma oficina interativa em 2D, um laborat\xf3rio 3D de desmontagem guiada de bomba centr\xedfuga, simuladores de paqu\xedmetro e rel\xf3gio comparador (TIR), al\xe9m de trilhas de quest\xf5es com passaporte de compet\xeancias salvo localmente no navegador.",en:"Mec\xe2nica Lab emerged from a direct observation while studying industrial mechanics: learning machine elements, metrology, and maintenance solely through static handouts makes it hard to visualize how components interact spatially. The platform combines an interactive 2D workshop, a 3D guided centrifugal pump disassembly lab, vernier caliper and dial indicator (TIR) simulators, and learning tracks with a browser-saved competency passport."},problem:{pt:"Estudantes de cursos t\xe9cnicos muitas vezes t\xeam tempo limitado em bancada f\xedsica e encontram dificuldade em conectar desenhos t\xe9cnicos 2D com a sequ\xeancia real de desmontagem de uma bomba centr\xedfuga ou com a leitura precisa de instrumentos de medi\xe7\xe3o como o paqu\xedmetro e o rel\xf3gio comparador.",en:"Technical students often have limited bench time and struggle to connect 2D engineering drawings with the real disassembly sequence of a centrifugal pump or accurate reading of measuring instruments like calipers and dial indicators."},concept:{pt:"Criar um ambiente digital leve e gratuito que funcione direto no navegador (computador ou celular), unindo navega\xe7\xe3o gamificada 2D por esta\xe7\xf5es de oficina com inspe\xe7\xe3o 3D de pe\xe7as e simuladores pr\xe1ticos de instrumentos.",en:"Create a lightweight, accessible digital environment running directly in the browser (desktop or mobile), combining gamified 2D workshop station navigation with 3D part inspection and hands-on instrument simulators."},solution:{pt:"Uma aplica\xe7\xe3o web modular constru\xedda com React, TypeScript, Three.js e Phaser 3. O aluno caminha pelas esta\xe7\xf5es da oficina 2D, entra no laborat\xf3rio 3D para inspecionar e desmontar passo a passo uma bomba centr\xedfuga, pratica leituras milim\xe9tricas no paqu\xedmetro e no rel\xf3gio comparador (TIR) e consolida o aprendizado em trilhas de revis\xe3o.",en:"A modular web application built with React, TypeScript, Three.js, and Phaser 3. Students navigate 2D workshop stations, enter the 3D lab to inspect and step-by-step disassemble a centrifugal pump, practice millimeter readings on the caliper and dial indicator (TIR), and consolidate knowledge through review tracks."},developmentProcess:{pt:["Mapeamento pedag\xf3gico dos temas essenciais de mec\xe2nica industrial: elementos de m\xe1quinas, bombas centr\xedfugas, metrologia e manuten\xe7\xe3o preventiva.","Arquitetura h\xedbrida isolando o motor 2D (Phaser) do WebGLRenderer 3D (Three.js) com descarte rigoroso de geometrias e materiais ao trocar de tela para garantir 60 FPS.","Desenvolvimento de simuladores interativos de rel\xf3gio comparador (leitura de excentricidade TIR) e paqu\xedmetro com gera\xe7\xe3o de exerc\xedcios pr\xe1ticos.","Implementa\xe7\xe3o de testes automatizados de ponta a ponta e acessibilidade com Playwright + axe-core."],en:["Pedagogical mapping of core industrial mechanics topics: machine elements, centrifugal pumps, metrology, and preventive maintenance.","Hybrid architecture isolating the 2D engine (Phaser) from the 3D WebGLRenderer (Three.js) with strict geometry and material disposal on route change to maintain 60 FPS.","Development of interactive dial indicator (TIR runout reading) and vernier caliper simulators with practical exercises.","Implementation of automated end-to-end and accessibility tests using Playwright + axe-core."]},myContribution:{pt:"Concep\xe7\xe3o integral do produto a partir da viv\xeancia como estudante de mec\xe2nica industrial, defini\xe7\xe3o pedag\xf3gica das esta\xe7\xf5es e sequ\xeancias mec\xe2nicas, desenvolvimento assistido por IA da aplica\xe7\xe3o em React/TypeScript/Three.js/Phaser, testes E2E e publica\xe7\xe3o.",en:"Full product conception rooted in real industrial mechanics training, pedagogical definition of stations and mechanical sequences, AI-assisted development in React/TypeScript/Three.js/Phaser, E2E testing, and deployment."},currentStatus:{pt:"Aplica\xe7\xe3o funcional publicada para demonstra\xe7\xe3o p\xfablica e c\xf3digo-fonte aberto no GitHub.",en:"Functional application published for public demonstration with open-source code on GitHub."},technologies:["React 18","TypeScript","Three.js","Phaser 3","Tailwind CSS","Vite","Playwright"],highlights:[{label:{pt:"Ambientes Integrados",en:"Integrated Environments"},value:"Oficina 2D + Lab 3D"},{label:{pt:"Simuladores T\xe9cnicos",en:"Technical Simulators"},value:"Bomba + TIR + Paqu\xedmetro"},{label:{pt:"Execu\xe7\xe3o",en:"Runtime"},value:"100% Browser (Zero Login)"}],gallery:[{src:"/projects/mecanica-lab/inicio.png",alt:{pt:"Tela inicial do Mec\xe2nica Lab mostrando a plataforma educacional interativa",en:"Mec\xe2nica Lab home screen showing the interactive educational platform"},caption:{pt:"Interface principal do Mec\xe2nica Lab com acesso \xe0 Oficina 2D, Laborat\xf3rio 3D de Bomba Centr\xedfuga e Simuladores de Metrologia.",en:"Mec\xe2nica Lab main interface with access to the 2D Workshop, 3D Centrifugal Pump Lab, and Metrology Simulators."}}]},{slug:"visionsafe-ai",index:"02",code:"IV-LAB // 02",maturity:"prototype",statusBadge:{pt:"Prot\xf3tipo Independente de Pesquisa (PoC)",en:"Independent Research Prototype (PoC)"},title:{pt:"VisionSafe AI — Verifica\xe7\xe3o de EPIs com Vis\xe3o Computacional no Dispositivo",en:"VisionSafe AI — On-Device Computer Vision PPE Verification"},subtitle:{pt:"Prova de conceito independente para reconhecimento de \xf3culos de seguran\xe7a, protetor auricular e touca direto no navegador do celular.",en:"Independent proof of concept for recognizing safety glasses, hearing protection, and hairnets directly in the mobile browser."},category:{pt:"Vis\xe3o Computacional \xb7 Edge AI \xb7 Seguran\xe7a Industrial",en:"Computer Vision \xb7 Edge AI \xb7 Industrial Safety"},year:"2026",heroImage:"/projects/visionsafe-ai/inicio.png",liveUrl:"https://visionsafe-ai-demo.netlify.app",githubUrl:"https://github.com/italovienna-sketch/visionsafe-ai",disclaimer:{pt:"Prova de conceito independente desenvolvida para estudo t\xe9cnico de vis\xe3o computacional aplicada a desafios de seguran\xe7a industrial. N\xe3o possui v\xednculo oficial com nenhuma empresa, n\xe3o utiliza imagens corporativas, n\xe3o \xe9 um sistema certificado e n\xe3o substitui a supervis\xe3o humana de seguran\xe7a do trabalho.",en:"Independent proof of concept developed for technical study of computer vision applied to industrial safety challenges. It has no official company affiliation, uses no corporate images, is not a certified system, and never replaces human occupational safety supervision."},overview:{pt:"O VisionSafe AI investiga como modelos leves de vis\xe3o computacional (YOLO11n rodando via ONNX Runtime Web em Web Worker) podem auxiliar na confer\xeancia visual de Equipamentos de Prote\xe7\xe3o Individual (\xf3culos de seguran\xe7a, protetor auricular e touca) usando apenas a c\xe2mera do celular, sem enviar ou gravar nenhuma imagem em servidores externos.",en:"VisionSafe AI investigates how lightweight computer vision models (YOLO11n running via ONNX Runtime Web in a Web Worker) can assist in visually checking Personal Protective Equipment (safety glasses, earplugs/earmuffs, and hairnets) using only a smartphone camera, without uploading or storing any images on external servers."},problem:{pt:"Sistemas tradicionais de vis\xe3o computacional para seguran\xe7a industrial costumam exigir servidores dedicados com GPU, c\xe2meras fixas de alto custo e transmiss\xe3o cont\xednua de v\xeddeo pela rede — gerando barreiras de privacidade, lat\xeancia e infraestrutura. Al\xe9m disso, detectores ing\xeanuos tratam qualquer falha de c\xe2mera ou oclus\xe3o como 'infra\xe7\xe3o', gerando falsos alarmes.",en:"Traditional industrial safety computer vision systems often require dedicated GPU servers, expensive fixed cameras, and continuous video streaming over the network — raising privacy, latency, and infrastructure barriers. Furthermore, naive detectors treat camera blur or occlusion as a 'violation', causing false alarms."},concept:{pt:"Processar 100% da infer\xeancia no pr\xf3prio aparelho (offline-first ap\xf3s o primeiro carregamento) e substituir decis\xf5es bin\xe1rias precipitadas por uma m\xe1quina de estados honesta sobre a incerteza \xf3ptica: Detectado, N\xe3o confirmado e N\xe3o avali\xe1vel.",en:"Process 100% of inference on-device (offline-first after initial load) and replace premature binary judgments with a state machine that is honest about optical uncertainty: Detected, Unconfirmed, and Not Evaluable."},solution:{pt:"Uma PWA em React + TypeScript que executa infer\xeancia com ONNX Runtime Web em Web Worker isolado. O sistema acompanha cada pessoa separadamente ao longo de uma janela temporal configur\xe1vel (5s) e informa tr\xeas estados claros por EPI: 'Detectado', 'N\xe3o confirmado' (quando o item n\xe3o foi visto na janela, cabendo sempre ao t\xe9cnico conferir) e 'N\xe3o avali\xe1vel' (quando a imagem est\xe1 distante, borrada, escura ou com baixa confian\xe7a — nunca acusando falsamente). Inclui ainda uma bancada de testes com gabarito (precis\xe3o, revoca\xe7\xe3o, lat\xeancia) e exporta\xe7\xe3o CSV.",en:"A React + TypeScript PWA running ONNX Runtime Web inference inside an isolated Web Worker. The system tracks each person separately across a configurable time window (5s) and reports three transparent states per PPE item: 'Detected', 'Unconfirmed' (requiring human technician verification), and 'Not Evaluable' (when the frame is too far, blurry, dark, or low-confidence — never falsely accusing). Includes a benchmark test suite (precision, recall, latency) with CSV export."},developmentProcess:{pt:["Constru\xe7\xe3o da interface mobile-first com controle expl\xedcito da c\xe2mera (indicador permanente de c\xe2mera ativa e libera\xe7\xe3o imediata de hardware ao parar).","Integra\xe7\xe3o do ONNX Runtime Web em Web Worker para manter a interface fluida enquanto modelos YOLO11n processam os quadros localmente.","Modelagem da m\xe1quina de estados por pessoa com janela temporal de 5 segundos e diagn\xf3stico de qualidade \xf3ptica (dist\xe2ncia, nitidez, ilumina\xe7\xe3o).","Cria\xe7\xe3o de 114 testes automatizados (unit\xe1rios com Vitest + E2E com Playwright) validando privacidade de rede (zero requisi\xe7\xf5es externas de imagem), modo offline e opera\xe7\xe3o cont\xednua."],en:["Mobile-first interface engineering with explicit camera lifecycle control (permanent active-camera indicator and immediate hardware release on stop).","ONNX Runtime Web integration inside a Web Worker to keep UI responsive while YOLO11n models process frames locally.","Per-person temporal state machine (5-second window) with optical quality diagnostics (distance, blur, lighting).","114 automated tests (Vitest unit + Playwright E2E) verifying network privacy (zero external image requests), offline mode, and prolonged operation."]},myContribution:{pt:"Idealiza\xe7\xe3o da prova de conceito inspirada em desafios reais de seguran\xe7a industrial, defini\xe7\xe3o das regras de estados de incerteza ('N\xe3o avali\xe1vel' vs. 'N\xe3o confirmado'), treinamento/exporta\xe7\xe3o experimental de modelos em Python e desenvolvimento assistido por IA da PWA e su\xedte de testes.",en:"Conception of the proof of concept inspired by real industrial safety challenges, definition of uncertainty state rules ('Not Evaluable' vs. 'Unconfirmed'), experimental model export in Python, and AI-assisted PWA and test suite development."},currentStatus:{pt:"Prot\xf3tipo experimental independente publicado para demonstra\xe7\xe3o t\xe9cnica (interface e pipeline validados; modelos de produ\xe7\xe3o restritos por licen\xe7a de dataset).",en:"Independent experimental prototype published for technical demonstration (interface and pipeline validated; weights restricted by dataset licensing)."},technologies:["React","TypeScript","ONNX Runtime Web","YOLO11n","Web Workers","PWA / Service Worker","Python","Vitest","Playwright"],highlights:[{label:{pt:"Privacidade",en:"Privacy"},value:"100% On-Device (Zero Upload)"},{label:{pt:"Estados por EPI",en:"PPE States"},value:"Detectado \xb7 N\xe3o Confirmado \xb7 N\xe3o Avali\xe1vel"},{label:{pt:"Qualidade & Testes",en:"Quality & Tests"},value:"114 Testes Automatizados"}],gallery:[{src:"/projects/visionsafe-ai/inicio.png",alt:{pt:"Interface do prot\xf3tipo VisionSafe AI para verifica\xe7\xe3o de EPIs no navegador",en:"VisionSafe AI prototype interface for browser-based PPE verification"},caption:{pt:"Tela do VisionSafe AI destacando o processamento local no dispositivo, estados de verifica\xe7\xe3o por EPI e painel de m\xe9tricas.",en:"VisionSafe AI screen highlighting on-device processing, per-PPE verification states, and metrics panel."}}]},{slug:"projetos-3d-industriais",index:"03",code:"IV-LAB // 03",maturity:"simulation",statusBadge:{pt:"Prot\xf3tipos 3D & Simula\xe7\xf5es T\xe9cnicas Verificadas",en:"Verified 3D Prototypes & Technical Simulations"},title:{pt:"Projetos 3D Industriais — PumpWise 3D (B-962-1A) & SmartStock 3D",en:"Industrial 3D Projects — PumpWise 3D (B-962-1A) & SmartStock 3D"},subtitle:{pt:"Desmontagem passo a passo em eixo mec\xe2nico real de bomba centr\xedfuga industrial e localiza\xe7\xe3o espacial 3D de almoxarifado a 60 FPS.",en:"True-axis step-by-step industrial centrifugal pump disassembly and 60 FPS 3D warehouse spatial localization."},category:{pt:"Engenharia Visual 3D \xb7 CAD Web \xb7 Simula\xe7\xe3o de Manuten\xe7\xe3o",en:"3D Visual Engineering \xb7 Web CAD \xb7 Maintenance Simulation"},year:"2026",heroImage:"/projects/pumpwise-3d/overview_04_exploded_hierarchy.png",videoPreview:"/projects/pumpwise-3d/demo.mp4",interactive3DModel:"/projects/pumpwise-3d/b9621a_pump.glb",disclaimer:{pt:"Prot\xf3tipos conceituais independentes (PumpWise 3D e SmartStock 3D) desenvolvidos para estudo de visualiza\xe7\xe3o t\xe9cnica e treinamento. Dados de estoque, SKUs e procedimentos s\xe3o estritamente educacionais/fict\xedcios e n\xe3o aprovados para uso operacional em campo sem valida\xe7\xe3o de engenharia.",en:"Independent conceptual prototypes (PumpWise 3D and SmartStock 3D) developed for technical visualization and training study. Inventory data, SKUs, and procedures are strictly educational/fictional and not approved for field use without engineering validation."},overview:{pt:"Esta frente do IV LABS re\xfane dois prot\xf3tipos tridimensionais voltados \xe0 rotina de manuten\xe7\xe3o industrial: (1) o PumpWise 3D, um guia interativo 3D de desmontagem, inspe\xe7\xe3o e remontagem passo a passo de uma bomba centr\xedfuga horizontal (refer\xeancia conceitual B-962-1A / IMBIL ST-4) com hierarquia real de componentes; e (2) o SmartStock 3D, um localizador espacial de pe\xe7as de almoxarifado (rolamentos, retentores, correias, parafusos) que posiciona a c\xe2mera automaticamente na prateleira e gaveta exatas com sinaliza\xe7\xe3o luminosa.",en:"This IV LABS track unites two 3D prototypes focused on industrial maintenance routines: (1) PumpWise 3D, an interactive 3D step-by-step disassembly, inspection, and reassembly guide for a horizontal centrifugal pump (conceptual reference B-962-1A / IMBIL ST-4) with true component hierarchy; and (2) SmartStock 3D, a spatial warehouse part locator (bearings, seals, belts, bolts) that automatically flies the camera to the exact shelf and drawer with pulsing beacon highlights."},problem:{pt:"Na manuten\xe7\xe3o mec\xe2nica, dois gargalos visuais s\xe3o recorrentes: compreender a ordem exata de extra\xe7\xe3o de fixadores, carca\xe7a, rotor, selo mec\xe2nico e rolamentos sem danificar componentes; e localizar rapidamente pe\xe7as de reposi\xe7\xe3o em almoxarifados com centenas de gavetas.",en:"In mechanical maintenance, two visual bottlenecks recur: understanding the exact extraction order of fasteners, casing, impeller, mechanical seal, and bearings without damaging parts; and quickly locating spare parts across warehouses with hundreds of drawers."},concept:{pt:"Aplicar WebGL e Three.js com rigor mec\xe2nico: vistas explodidas que respeitam o eixo real de extra\xe7\xe3o de cada pe\xe7a (axial/radial) e renderiza\xe7\xe3o instanciada (InstancedMesh) capaz de exibir centenas de gavetas de almoxarifado a 60 FPS.",en:"Apply WebGL and Three.js with mechanical rigor: exploded views respecting each component's true extraction axis (axial/radial) and instanced rendering (InstancedMesh) capable of displaying hundreds of warehouse drawers at 60 FPS."},solution:{pt:"No PumpWise 3D, um pipeline automatizado gera e valida os modelos GLB (208 KB para a bomba isolada), sincronizando 19 etapas de desmontagem, 10 de inspe\xe7\xe3o e 18 de remontagem com corte em raio-X e vistas explodidas. J\xe1 no SmartStock 3D, uma arquitetura React + Three.js + Zustand + Fuse.js conecta a busca textual/fon\xe9tica de pe\xe7as diretamente \xe0s coordenadas 3D da g\xf4ndola correspondente.",en:"In PumpWise 3D, an automated pipeline generates and validates GLB models (208 KB for the pump assembly), synchronizing 19 disassembly steps, 10 inspection steps, and 18 reassembly steps with X-ray cutaway and exploded views. In SmartStock 3D, a React + Three.js + Zustand + Fuse.js architecture connects fuzzy/phonetic part search directly to the 3D coordinates of the corresponding rack and drawer."},developmentProcess:{pt:["Modelagem e organiza\xe7\xe3o hier\xe1rquica dos subconjuntos da bomba centr\xedfuga (voluta, tampa de suc\xe7\xe3o, rotor fechado, eixo, caixa de mancal, selo mec\xe2nico e fixadores).","Otimiza\xe7\xe3o dos arquivos 3D com @gltf-transform/cli reduzindo o modelo principal b9621a_pump.glb para apenas 208 KB para carregamento instant\xe2neo na web.","Renderiza\xe7\xe3o de vistas t\xe9cnicas (frontal 3/4, acionamento, raio-X lateral e \xe1rvore explodida) e anima\xe7\xe3o em v\xeddeo da sequ\xeancia completa de desmontagem/remontagem.","Desenvolvimento do SmartStock 3D com InstancedMesh, estado desacoplado em Zustand e su\xedte de valida\xe7\xe3o automatizada com Playwright."],en:["Modeling and hierarchical organization of centrifugal pump sub-assemblies (volute casing, suction cover, closed impeller, shaft, bearing housing, mechanical seal, and fasteners).","3D asset optimization using @gltf-transform/cli, compressing the main b9621a_pump.glb model to just 208 KB for instant web loading.","Technical view rendering (front 3/4, drive end, side X-ray, and exploded hierarchy) and video animation of the complete disassembly/reassembly sequence.","Development of SmartStock 3D using InstancedMesh, decoupled Zustand state, and automated Playwright validation."]},myContribution:{pt:"Estrutura\xe7\xe3o t\xe9cnica da sequ\xeancia de desmontagem/inspe\xe7\xe3o/remontagem baseada nos conceitos de mec\xe2nica industrial, cria\xe7\xe3o dos pipelines de gera\xe7\xe3o/valida\xe7\xe3o 3D e desenvolvimento assistido por IA dos visualizadores interativos.",en:"Technical structuring of the disassembly/inspection/reassembly sequence based on industrial mechanics fundamentals, creation of 3D generation/validation pipelines, and AI-assisted development of the interactive viewers."},currentStatus:{pt:"Prot\xf3tipos locais verificados com modelos GLB, renderiza\xe7\xf5es em alta defini\xe7\xe3o e v\xeddeos demonstrativos embarcados diretamente nesta p\xe1gina de estudo de caso.",en:"Verified local prototypes with GLB models, high-definition renders, and demonstration videos embedded directly inside this case study page."},technologies:["Three.js","GLTF / GLB","@gltf-transform/cli","React Three Fiber / Drei","TypeScript","Zustand","Fuse.js","Vite","Playwright"],highlights:[{label:{pt:"Modelo 3D Otimizado",en:"Optimized 3D Model"},value:"208 KB (.GLB Interativo)"},{label:{pt:"Roteiro T\xe9cnico",en:"Technical Procedure"},value:"47 Etapas (Desmontagem \xb7 Inspe\xe7\xe3o \xb7 Montagem)"},{label:{pt:"Performance 3D",en:"3D Performance"},value:"60 FPS + InstancedMesh"}],gallery:[{src:"/projects/pumpwise-3d/overview_04_exploded_hierarchy.png",alt:{pt:"Vista explodida hier\xe1rquica da bomba centr\xedfuga B-962-1A",en:"Exploded hierarchical view of the B-962-1A centrifugal pump"},caption:{pt:"Vista explodida no eixo mec\xe2nico real destacando voluta, rotor, selo mec\xe2nico, eixo e caixa de mancal.",en:"True mechanical axis exploded view highlighting volute, impeller, mechanical seal, shaft, and bearing housing."}},{src:"/projects/pumpwise-3d/overview_03_pump_xray_side.png",alt:{pt:"Vista lateral em raio-X da bomba centr\xedfuga mostrando componentes internos",en:"Side X-ray cutaway view of the centrifugal pump showing internal components"},caption:{pt:"Modo Raio-X lateral para inspe\xe7\xe3o da montagem interna do eixo, rolamentos e alojamento do selo.",en:"Side X-ray mode for inspecting internal shaft, bearings, and seal chamber assembly."}},{src:"/projects/pumpwise-3d/overview_01_assembly_front34.png",alt:{pt:"Conjunto montado frontal 3/4 da bomba centr\xedfuga com base e motor",en:"Front 3/4 assembled view of the centrifugal pump with skid base and motor"},caption:{pt:"Conjunto completo montado na base met\xe1lica com acoplamento, prote\xe7\xe3o e motor el\xe9trico.",en:"Complete assembly mounted on metallic skid base with coupling guard and electric motor."}},{src:"/projects/pumpwise-3d/overview_02_assembly_drive34.png",alt:{pt:"Vista 3/4 do lado do acionamento do conjunto motobomba",en:"Drive-end 3/4 view of the motor-pump assembly"},caption:{pt:"Perspectiva do lado do acionamento (Drive End) utilizada na etapa de alinhamento e bloqueio seguro.",en:"Drive-end perspective used during alignment and lockout/tagout verification steps."}}]},{slug:"digitalizacao-industrial",index:"04",code:"IV-LAB // 04",maturity:"prototype",statusBadge:{pt:"Prot\xf3tipo Funcional Publicado & Experimento SCADA",en:"Published Functional Prototype & SCADA Experiment"},title:{pt:"Digitaliza\xe7\xe3o Industrial — Maintenance Intelligence 360 & ETA 4.0",en:"Industrial Digitalization — Maintenance Intelligence 360 & ETA 4.0"},subtitle:{pt:"Hist\xf3rico visual por m\xe1quina no celular com poucos toques, SQLite em WebAssembly e supervis\xe3o de processos.",en:"Touch-first mobile machine history, in-browser SQLite WebAssembly, and process supervision."},category:{pt:"Sistemas de Manuten\xe7\xe3o \xb7 Ind\xfastria 4.0 \xb7 Interfaces Operacionais",en:"Maintenance Systems \xb7 Industry 4.0 \xb7 Operational Interfaces"},year:"2026",heroImage:"/projects/mi360/inicio.png",liveUrl:"https://maintenance-360-demo.netlify.app",githubUrl:"https://github.com/italovienna-sketch/maintenance-intelligence-360",disclaimer:{pt:"Projetos independentes (Maintenance Intelligence 360 e prot\xf3tipo ETA 4.0) constru\xeddos exclusivamente com dados fict\xedcios (equipamentos, operadores e documentos inventados). O assistente t\xe9cnico n\xe3o usa IA generativa ao vivo para autorizar manobras — toda decis\xe3o e confirma\xe7\xe3o \xe9 estritamente humana.",en:"Independent projects (Maintenance Intelligence 360 and ETA 4.0 prototype) built exclusively with fictional data (invented equipment, operators, and documents). The technical assistant never autonomously authorizes maintenance actions — all decisions and confirmations are strictly human."},overview:{pt:"Cada m\xe1quina no ch\xe3o de f\xe1brica tem uma hist\xf3ria, mas muitas vezes essa hist\xf3ria se perde em anota\xe7\xf5es dispersas ou formul\xe1rios dif\xedceis de preencher no celular. O Maintenance Intelligence 360 \xe9 um prot\xf3tipo de plataforma visual de manuten\xe7\xe3o pensado para o mec\xe2nico registrar interven\xe7\xf5es por toques r\xe1pidos (sem digitar longos textos), consultar a mem\xf3ria de pe\xe7as trocadas em 3D, gerar o relat\xf3rio di\xe1rio em PDF e consultar um assistente baseado em fontes que separa claramente fatos do hist\xf3rico, hip\xf3teses e inspe\xe7\xf5es recomendadas. Complementando essa frente, o experimento local ETA 4.0 explora interfaces supervis\xf3rias (P&ID 2D interativo em SVG, padr\xe3o Select-Before-Operate e gest\xe3o de alarmes ISA-18.2).",en:"Every shop-floor machine has a story, yet that history is often lost in scattered notes or clunky forms. Maintenance Intelligence 360 is a visual maintenance platform prototype designed for mechanics to log interventions via quick taps (without typing long texts), inspect 3D part replacement history, export daily PDF reports, and query a source-grounded assistant that strictly separates historical facts, hypotheses, and recommended inspections. Complementing this track, the local ETA 4.0 experiment explores supervisory interfaces (interactive 2D SVG P&ID, Select-Before-Operate pattern, and ISA-18.2 alarm management)."},problem:{pt:"Com as m\xe3os ocupadas ou usando EPIs na oficina, digitar relat\xf3rios complexos em sistemas tradicionais \xe9 lento. Como consequ\xeancia, registros ficam incompletos e o hist\xf3rico de falhas recorrentes de uma bomba ou redutor n\xe3o chega de forma clara ao pr\xf3ximo turno.",en:"With hands occupied or wearing PPE on the shop floor, typing complex reports into legacy systems is slow. Consequently, logs remain incomplete and recurring failure patterns on a pump or gearbox fail to reach the next shift clearly."},concept:{pt:"Priorizar 'toques em vez de digita\xe7\xe3o' no celular, unindo cat\xe1logo visual de equipamentos em 3D, busca instant\xe2nea sem acento (SQLite FTS5) e execu\xe7\xe3o 100% no navegador via SQLite em WebAssembly para demonstra\xe7\xe3o imediata.",en:"Prioritize 'taps over typing' on mobile, uniting a visual 3D equipment catalog, instant accent-insensitive search (SQLite FTS5), and 100% in-browser execution via SQLite WebAssembly for zero-setup demonstration."},solution:{pt:"Arquitetura unificada em TypeScript + Hono + SQLite (FTS5) + Zod + Three.js. No servidor local roda sobre Node 24; na demonstra\xe7\xe3o p\xfablica publicada, a mesma API executa inteiramente no navegador do visitante com SQLite compilado para WebAssembly. Inclui ainda o prot\xf3tipo complementar ETA 4.0 (FastAPI + React) focado em sin\xf3tico P&ID, correla\xe7\xe3o de primeira falha (First-Out) e monitoramento de severidade de vibra\xe7\xe3o ISO 10816-3.",en:"Unified architecture in TypeScript + Hono + SQLite (FTS5) + Zod + Three.js. Locally it runs on Node 24; in the published public demo, the exact same API runs entirely inside the visitor's browser via SQLite compiled to WebAssembly. Also includes the complementary ETA 4.0 prototype (FastAPI + React) focused on P&ID synoptics, First-Out fault correlation, and ISO 10816-3 vibration severity monitoring."},developmentProcess:{pt:["Modelagem do banco de dados relacional e \xedndice de busca full-text (SQLite FTS5) para localizar m\xe1quinas, sintomas e manuais mesmo sem acentua\xe7\xe3o.","Desenvolvimento do fluxo de registro r\xe1pido por toques (m\xe1quina, local, mec\xe2nico, sintoma, servi\xe7o executado e resultado) e gerador de relat\xf3rio di\xe1rio em PDF.","Implementa\xe7\xe3o do Assistente com Fontes determin\xedstico: separa fatos registrados no hist\xf3rico, hip\xf3teses t\xe9cnicas e inspe\xe7\xf5es recomendadas, exigindo sempre confirma\xe7\xe3o humana.","Compila\xe7\xe3o da camada de persist\xeancia para SQLite em WebAssembly permitindo que qualquer recrutador ou engenheiro teste o sistema completo no navegador sem backend externo."],en:["Relational database modeling and full-text search indexing (SQLite FTS5) to locate machines, symptoms, and manuals even without accents.","Development of the touch-first logging workflow (machine, location, mechanic, symptom, action taken, outcome) and daily PDF report generator.","Implementation of the deterministic Source-Grounded Assistant: separates recorded historical facts, technical hypotheses, and recommended inspections, always requiring human confirmation.","Compilation of the persistence layer to SQLite WebAssembly, enabling any recruiter or engineer to test the full system in-browser without an external backend."]},myContribution:{pt:"Desenho da experi\xeancia de uso focada na realidade do mec\xe2nico em campo, modelagem dos dados de manuten\xe7\xe3o e cen\xe1rios operacionais, e desenvolvimento assistido por IA da API Hono/SQLite, camada WebAssembly, visualiza\xe7\xe3o 3D e testes multi-viewport.",en:"User experience design grounded in field mechanic workflows, maintenance data and operational scenario modeling, and AI-assisted development of the Hono/SQLite API, WebAssembly layer, 3D visualization, and multi-viewport tests."},currentStatus:{pt:"Maintenance Intelligence 360 publicado com demonstra\xe7\xe3o interativa online e reposit\xf3rio aberto no GitHub; prot\xf3tipo ETA 4.0 documentado localmente.",en:"Maintenance Intelligence 360 published with live interactive demo and open GitHub repository; ETA 4.0 prototype documented locally."},technologies:["TypeScript","Node.js","Hono","SQLite (FTS5 & WASM)","Three.js","Zod","FastAPI (ETA 4.0)","Vitest","Playwright"],highlights:[{label:{pt:"Interface de Campo",en:"Field Interface"},value:"Registro R\xe1pido por Toques"},{label:{pt:"Banco no Navegador",en:"In-Browser DB"},value:"SQLite + FTS5 via WebAssembly"},{label:{pt:"Seguran\xe7a Operacional",en:"Operational Safety"},value:"Fatos vs. Hip\xf3teses (Confirma\xe7\xe3o Humana)"}],gallery:[{src:"/projects/mi360/inicio.png",alt:{pt:"Tela inicial do Maintenance Intelligence 360 com cat\xe1logo visual e bomba 3D",en:"Maintenance Intelligence 360 home screen with visual catalog and 3D pump"},caption:{pt:"Vis\xe3o de equipamentos com hist\xf3rico por m\xe1quina e inspe\xe7\xe3o de componentes em 3D.",en:"Equipment view with per-machine history and 3D component inspection."}},{src:"/projects/mi360/registro.png",alt:{pt:"Tela de registro de manuten\xe7\xe3o por toques r\xe1pidos no celular",en:"Touch-based maintenance logging screen on mobile"},caption:{pt:"Fluxo de registro pensado para o celular: sele\xe7\xe3o r\xe1pida de equipamento, sintoma, servi\xe7o e resultado sem digita\xe7\xe3o longa.",en:"Mobile-first logging flow: rapid selection of equipment, symptom, service, and outcome without long typing."}},{src:"/projects/mi360/relatorio.png",alt:{pt:"Tela de relat\xf3rio di\xe1rio de manuten\xe7\xe3o com m\xe9tricas e exporta\xe7\xe3o PDF",en:"Daily maintenance report screen with metrics and PDF export"},caption:{pt:"Relat\xf3rio consolidado do turno com contagens reais por mec\xe2nico, local e status, pronto para exporta\xe7\xe3o em PDF.",en:"Consolidated shift report with real counts by mechanic, area, and status, ready for PDF export."}},{src:"/projects/mi360/assistente.png",alt:{pt:"Tela do assistente t\xe9cnico com separa\xe7\xe3o entre fatos, hip\xf3teses e inspe\xe7\xf5es",en:"Technical assistant screen separating facts, hypotheses, and inspections"},caption:{pt:"Assistente baseado em fontes: separa estritamente fatos do hist\xf3rico da m\xe1quina, hip\xf3teses e inspe\xe7\xf5es recomendadas.",en:"Source-grounded assistant: strictly separates historical machine facts, hypotheses, and recommended inspections."}}]}]},4889:(e,a,o)=>{o.d(a,{LanguageProvider:()=>s,o:()=>r});var i=o(5155),t=o(2115);let n=(0,t.createContext)({locale:"pt",setLocale:()=>{},toggleLocale:()=>{}});function s(e){let{children:a}=e,[o,s]=(0,t.useState)("pt");(0,t.useEffect)(()=>{try{let e=window.localStorage.getItem("ivlabs_locale");("pt"===e||"en"===e)&&s(e)}catch(e){}},[]);let r=e=>{s(e);try{window.localStorage.setItem("ivlabs_locale",e),document.documentElement.lang="pt"===e?"pt-BR":"en"}catch(e){}};return(0,i.jsx)(n.Provider,{value:{locale:o,setLocale:r,toggleLocale:()=>{r("pt"===o?"en":"pt")}},children:a})}function r(){return(0,t.useContext)(n)}}}]);